content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #cbd5e1;
  --radius: 0.5rem;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);

  /* スペーシング変数 */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #3b82f6;
    --primary-hover: #2563eb;
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.5), 0 2px 4px -2px rgb(0 0 0 / 0.5);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: var(--space-md);
}

.app-container {
  max-width: 800px;
  margin: 0 auto;
  padding: var(--space-md);
}

.header {
  text-align: center;
  margin-bottom: var(--space-xl);
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: var(--space-sm);
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
}

.main-content {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: var(--space-lg);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

.form-group {
  margin-bottom: 1.25rem;
}

.label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--space-sm);
  font-size: 0.95rem;
}

.input, .select {
  width: 100%;
  padding: 0.75rem;
  background-color: var(--card-bg);
  color: var(--text-main);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  font-size: 1rem;
  outline: 2px solid transparent;
  outline-offset: 2px;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus, .select:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.2);
  outline: 2px solid var(--primary-color);
}

.presets {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin-top: var(--space-sm);
}

.preset-btn {
  background-color: #eff6ff;
  color: var(--primary-color);
  border: 1px solid #bfdbfe;
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius);
  font-size: 0.85rem;
  cursor: pointer;
  transition: background-color 0.2s;
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.preset-btn:focus {
  outline: 2px solid var(--primary-color);
}

@media (prefers-color-scheme: dark) {
  .preset-btn {
    background-color: #1e3a8a;
    color: #93c5fd;
    border-color: #1d4ed8;
  }
}

.preset-btn:hover {
  background-color: #dbeafe;
}

@media (prefers-color-scheme: dark) {
  .preset-btn:hover {
    background-color: #1e40af;
  }
}

.results-section {
  margin-top: var(--space-lg);
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-md);
  margin-top: var(--space-md);
}

.result-card {
  background-color: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: var(--space-md);
  text-align: center;
}

.result-unit {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-transform: uppercase;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.result-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  word-break: break-all;
}

.btn {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 0.6rem 1.2rem;
  border-radius: var(--radius);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.btn:focus {
  outline: 2px solid var(--primary-color);
}

.btn:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: var(--border-color);
  color: var(--text-main);
  border: none;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-size: 0.9rem;
  cursor: pointer;
  transition: background-color 0.2s;
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.btn-secondary:focus {
  outline: 2px solid var(--text-main);
}

.btn-secondary:hover {
  opacity: 0.9;
}

.history-section {
  margin-top: var(--space-lg);
}

.history-list {
  list-style: none;
  margin-top: var(--space-md);
  max-height: 250px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem;
  background-color: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  font-size: 0.9rem;
}

@media (max-width: 480px) {
  .title {
    font-size: 1.5rem;
  }
  .card {
    padding: var(--space-md);
  }
}

/**
 * 単位のカテゴリ（将来的な他の単位（重量など）の追加を見越した拡張用）
 */
export type UnitCategory = 'length' | 'weight' | 'temperature';

/**
 * 対応している長さの単位の種類
 */
export type UnitType = 'mm' | 'cm' | 'm' | 'km' | 'inch' | 'foot';

/**
 * 単位変換の履歴レコード
 */
export interface ConversionRecord {
  /** 履歴の一意な識別子 */
  id: string;
  /** 入力された数値 */
  value: number;
  /** 変換元の単位 */
  fromUnit: UnitType;
  /** 変換が行われた日時のタイムスタンプ文字列 */
  timestamp: string;
  /** 表示用の精度やフォーマットに関する情報（オプション） */
  precision?: number;
}

/**
 * 入力値のバリデーション結果を表す型
 */
export interface ValidationResult {
  /** 入力値が有効かどうか */
  isValid: boolean;
  /** エラーメッセージ（無効な場合） */
  errorMessage?: string;
}

import { useState, useCallback, useEffect } from 'react';
import './index.css';
import { UnitType, ConversionRecord } from './types';
import ConverterForm from './ConverterForm';
import ConversionHistory from './ConversionHistory';

const STORAGE_KEY = 'length_converter_history';
const MAX_HISTORY_COUNT = 50;

export default function App() {
  const [history, setHistory] = useState<ConversionRecord[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          return parsed;
        }
      }
    } catch (error) {
      console.error('Failed to load history from localStorage:', error);
    }
    return [];
  });

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(history));
    } catch (error) {
      console.error('Failed to save history to localStorage:', error);
    }
  }, [history]);

  const handleAddHistory = useCallback((value: number, fromUnit: UnitType) => {
    const newRecord: ConversionRecord = {
      id: Date.now().toString(),
      value,
      fromUnit,
      timestamp: new Date().toLocaleTimeString(),
    };
    setHistory((prev) => [newRecord, ...prev].slice(0, MAX_HISTORY_COUNT));
  }, []);

  const handleClearHistory = useCallback(() => {
    setHistory([]);
  }, []);

  const handleDeleteHistory = useCallback((id: string) => {
    setHistory((prev) => prev.filter((item) => item.id !== id));
  }, []);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">単位変換ツール</h1>
        <p className="subtitle">mm・cm・m・km・インチ・フィートをリアルタイムで相互変換</p>
      </header>

      <main className="main-content">
        <ConverterForm onConvert={handleAddHistory} />
        <ConversionHistory
          items={history}
          onClear={handleClearHistory}
          onDelete={handleDeleteHistory}
        />
      </main>
    </div>
  );
}

import { useState, useMemo, useEffect, ChangeEvent } from 'react';
import './index.css';
import { UnitType } from './types';

interface ConverterFormProps {
  onConvert?: (value: number, fromUnit: UnitType) => void;
}

const UNIT_LABELS: Record<UnitType, string> = {
  mm: 'ミリメートル (mm)',
  cm: 'センチメートル (cm)',
  m: 'メートル (m)',
  km: 'キロメートル (km)',
  inch: 'インチ (in)',
  foot: 'フィート (ft)',
};

// 基準単位（mm）への変換レート
const TO_MM_RATES: Record<UnitType, number> = {
  mm: 1,
  cm: 10,
  m: 1000,
  km: 1000000,
  inch: 25.4,
  foot: 304.8,
};

export default function ConverterForm({ onConvert }: ConverterFormProps) {
  const [value, setValue] = useState<string>('1');
  const [fromUnit, setFromUnit] = useState<UnitType>('m');
  const [copiedUnit, setCopiedUnit] = useState<string | null>(null);

  const numericValue = useMemo(() => {
    const num = parseFloat(value);
    return isNaN(num) ? 0 : num;
  }, [value]);

  // すべての単位への換算値を計算
  const convertedValues = useMemo(() => {
    const valueInMm = numericValue * TO_MM_RATES[fromUnit];

    const result: Record<UnitType, number> = {
      mm: valueInMm / TO_MM_RATES.mm,
      cm: valueInMm / TO_MM_RATES.cm,
      m: valueInMm / TO_MM_RATES.m,
      km: valueInMm / TO_MM_RATES.km,
      inch: valueInMm / TO_MM_RATES.inch,
      foot: valueInMm / TO_MM_RATES.foot,
    };
    return result;
  }, [numericValue, fromUnit]);

  // 入力値変更時のデバウンス処理による履歴追加
  useEffect(() => {
    if (isNaN(numericValue) || numericValue < 0) return;
    const timer = setTimeout(() => {
      onConvert?.(numericValue, fromUnit);
    }, 800);

    return () => clearTimeout(timer);
  }, [numericValue, fromUnit, onConvert]);

  const handleChangeValue = (e: ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val !== '' && parseFloat(val) < 0) {
      return;
    }
    setValue(val);
  };

  const handleChangeUnit = (e: ChangeEvent<HTMLSelectElement>) => {
    const unit = e.target.value as UnitType;
    setFromUnit(unit);
  };

  const handlePresetClick = (presetValue: string, presetUnit: UnitType) => {
    setValue(presetValue);
    setFromUnit(presetUnit);
    const num = parseFloat(presetValue);
    if (!isNaN(num)) {
      onConvert?.(num, presetUnit);
    }
  };

  const handleCopy = (text: string, unitKey: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedUnit(unitKey);
      setTimeout(() => setCopiedUnit(null), 1500);
    });
  };

  return (
    <div className="card">
      <div className="form-group">
        <label className="label">数値を入力</label>
        <input
          type="number"
          className="input"
          value={value}
          onChange={handleChangeValue}
          min="0"
          step="any"
          placeholder="数値を入力してください"
        />
      </div>

      <div className="form-group">
        <label className="label">変換元の単位</label>
        <select className="select" value={fromUnit} onChange={handleChangeUnit}>
          {(Object.keys(UNIT_LABELS) as UnitType[]).map((unit) => (
            <option key={unit} value={unit}>
              {UNIT_LABELS[unit]}
            </option>
          ))}
        </select>
      </div>

      <div className="form-group">
        <label className="label">プリセット</label>
        <div className="presets">
          <button className="preset-btn" onClick={() => handlePresetClick('10', 'mm')}>10 mm</button>
          <button className="preset-btn" onClick={() => handlePresetClick('50', 'cm')}>50 cm</button>
          <button className="preset-btn" onClick={() => handlePresetClick('1', 'm')}>1 m</button>
          <button className="preset-btn" onClick={() => handlePresetClick('5', 'km')}>5 km</button>
          <button className="preset-btn" onClick={() => handlePresetClick('12', 'inch')}>12 インチ</button>
          <button className="preset-btn" onClick={() => handlePresetClick('6', 'foot')}>6 フィート</button>
        </div>
      </div>

      <div className="results-section">
        <label className="label">変換結果 (クリックしてコピー)</label>
        <div className="result-grid">
          {(Object.keys(UNIT_LABELS) as UnitType[]).map((unit) => {
            const val = convertedValues[unit];
            const formattedVal = Math.abs(val) < 0.000001 && val !== 0 
              ? val.toExponential(4) 
              : Number(val.toFixed(6)).toString();

            return (
              <div 
                key={unit} 
                className="result-card"
                onClick={() => handleCopy(formattedVal, unit)}
                style={{ cursor: 'pointer', position: 'relative' }}
                title="クリックしてコピー"
              >
                <div className="result-unit">{UNIT_LABELS[unit]}</div>
                <div className="result-value">{formattedVal}</div>
                {copiedUnit === unit && (
                  <div style={{ fontSize: '0.75rem', color: 'var(--primary-color)', marginTop: '0.25rem', fontWeight: 600 }}>
                    コピーしました！
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import './index.css';
import { ConversionRecord, UnitType } from './types';

interface ConversionHistoryProps {
  items?: ConversionRecord[];
  onClear?: () => void;
  onDelete?: (id: string) => void;
}

const UNIT_SHORT: Record<UnitType, string> = {
  mm: 'mm',
  cm: 'cm',
  m: 'm',
  km: 'km',
  inch: 'in',
  foot: 'ft',
};

export default function ConversionHistory({
  items = [],
  onClear,
  onDelete,
}: ConversionHistoryProps) {
  const handleClearWithConfirm = () => {
    if (window.confirm('すべての変換履歴をクリアしてもよろしいですか？')) {
      onClear?.();
    }
  };

  return (
    <div className="card history-section">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <label className="label" style={{ margin: 0 }}>変換履歴</label>
        {items.length > 0 && (
          <button className="btn-secondary" onClick={handleClearWithConfirm}>
            履歴をクリア
          </button>
        )}
      </div>
      {items.length === 0 ? (
        <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem', marginTop: '1rem', textAlign: 'center' }}>
          変換履歴はまだありません。
        </p>
      ) : (
        <ul className="history-list">
          {items.map((item) => (
            <li key={item.id} className="history-item">
              <span>
                <strong>{item.value} {UNIT_SHORT[item.fromUnit]}</strong> <span style={{ color: 'var(--text-muted)', fontSize: '0.8rem' }}>({item.timestamp})</span>
              </span>
              <button
                className="btn-secondary"
                style={{ padding: '0.25rem 0.5rem', fontSize: '0.8rem' }}
                onClick={() => onDelete?.(item.id)}
              >
                削除
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
